<?php
declare(strict_types=1);require_once __DIR__.'/config/sales_step15.php';$error=null;$dataset=(string)($_GET['dataset']??'fulfillment');$download=(string)($_GET['download']??'')==='csv';$rows=[];$headers=[];
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($dataset==='customers'){$headers=['Customer Code','Customer','Mobile','Email','Type','Status'];foreach(sales_step15_customers($pdo,$orgId) as $r)$rows[]=[(string)$r['customer_code'],(string)$r['customer_name'],(string)($r['mobile']??''),(string)($r['email']??''),(string)$r['customer_type'],(string)$r['status']];}elseif($dataset==='deliveries'){$headers=['Dispatch','Order','Date','Mode','Carrier','Tracking','Status'];$s=$pdo->prepare("SELECT * FROM sales_deliveries WHERE organization_id=? ORDER BY dispatch_date DESC,id DESC");$s->execute([$orgId]);foreach($s->fetchAll() as $r)$rows[]=[(string)$r['dispatch_number'],(string)$r['order_id'],(string)$r['dispatch_date'],(string)$r['delivery_mode'],(string)($r['carrier_name']??''),(string)($r['tracking_number']??''),(string)$r['status']];}elseif($dataset==='returns'){$headers=['Return','Order','Date','Credit','Reason','Status'];$s=$pdo->prepare("SELECT * FROM sales_returns WHERE organization_id=? ORDER BY return_date DESC,id DESC");$s->execute([$orgId]);foreach($s->fetchAll() as $r)$rows[]=[(string)$r['return_number'],(string)$r['order_id'],(string)$r['return_date'],(string)$r['total_credit'],(string)$r['reason'],(string)$r['status']];}elseif($dataset==='refunds'){$headers=['Refund ID','Order','Date','Amount','Method','Reference','Reason','Status'];$s=$pdo->prepare("SELECT * FROM sales_refunds WHERE organization_id=? ORDER BY refund_date DESC,id DESC");$s->execute([$orgId]);foreach($s->fetchAll() as $r)$rows[]=[(string)$r['id'],(string)$r['order_id'],(string)$r['refund_date'],(string)$r['amount'],(string)$r['refund_method'],(string)($r['reference_no']??''),(string)$r['reason'],(string)$r['status']];}elseif($dataset==='followups'){$headers=['Customer','Type','Interaction','Subject','Notes','Next Follow-up','Status'];$s=$pdo->prepare("SELECT c.customer_name,i.* FROM crm_interactions i JOIN crm_customers c ON c.id=i.customer_id AND c.organization_id=i.organization_id WHERE i.organization_id=? ORDER BY i.interaction_date DESC,i.id DESC");$s->execute([$orgId]);foreach($s->fetchAll() as $r)$rows[]=[(string)$r['customer_name'],(string)$r['interaction_type'],(string)$r['interaction_date'],(string)($r['subject']??''),(string)$r['notes'],(string)($r['next_followup_at']??''),(string)$r['status']];}else{$dataset='fulfillment';$headers=['Order','Date','Customer','Invoice','Delivery','Original Charge','Return Credit','Effective Charge','Gross Collected','Refund','Net Collected','Receivable','Customer Credit Due'];foreach(sales_step15_sales_rows($pdo,$orgId) as $r)$rows[]=[(string)$r['order_id'],(string)$r['order_date'],(string)$r['customer_name'],(string)($r['invoice_number']??''),(string)$r['delivery_status'],(string)$r['original_charge'],(string)$r['return_credit'],(string)$r['effective_charge'],(string)$r['gross_collected'],(string)$r['refund_amount'],(string)$r['net_collected'],(string)$r['receivable_amount'],(string)$r['customer_credit_due']];}if($download){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="step15_'.$dataset.'_'.date('Ymd').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,$headers);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}}catch(Throwable $e){$error=$e->getMessage();}
function sx_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>STEP 15 Export - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>@media print{.os-topbar,.os-sidebar,.no-print{display:none!important}.os-layout,.os-main{display:block!important;width:100%!important;margin:0!important}.os-card{box-shadow:none!important}}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="sales_fulfillment.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Export Center</small></span></a><div class="os-top-actions"><a class="os-btn" href="?dataset=<?= sx_h($dataset) ?>&download=csv">Download CSV</a><button class="os-btn primary" onclick="window.print()">Print / Save PDF</button></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Export Dataset</div><nav class="os-nav"><?php foreach(['fulfillment'=>'Fulfillment','customers'=>'Customers','deliveries'=>'Deliveries','returns'=>'Returns','refunds'=>'Refunds','followups'=>'Follow-ups'] as $k=>$v):?><a class="<?= $dataset===$k?'active':'' ?>" href="?dataset=<?= sx_h($k) ?>"><i class="dot"></i><?= sx_h($v) ?></a><?php endforeach;?></nav></aside><main class="os-main"><section class="os-hero pp-hero no-print"><div class="os-kicker">STEP 15J • CSV / PRINT EXPORT</div><h1>Export Customer CRM and after-sales data without changing source records.</h1><p>CSV uses UTF-8 BOM for Excel compatibility; Print can be saved as PDF from the browser.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'EXPORT READY':'Review required' ?></span><span class="os-chip"><?= count($rows) ?> rows</span><span class="os-chip"><?= sx_h(strtoupper($dataset)) ?></span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Export diagnostic:</strong> <?= sx_h($error) ?></div><?php endif;?><?php if(!$error):?><section class="os-card" style="margin-top:14px"><h2><?= sx_h(ucwords($dataset)) ?> Export</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><?php foreach($headers as $h):?><th><?= sx_h($h) ?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?= sx_h($v) ?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?= max(1,count($headers)) ?>">No data in this dataset yet.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?><div class="os-footer-note"><strong>Export rule:</strong> exported values are read-only snapshots of current STEP 15 data.</div></main></div></body></html>